local _, WFJ = ...
WFJ.Data.add("spell", {
  [425102] = { "Incidi sulla tua cintura la runa Coltello Avvelenato:\n\n$I1\nLancia istantaneamente l'arma nella mano secondaria, infliggendo i normali danni dell'arma secondaria con il $N1% di probabilità di applicare al bersaglio il veleno dell'arma secondaria. Fornisce $N2 punti combo. Restituisce $N3 energia per ogni applicazione di Veleno Mortale sul bersaglio.\n\nColtello Avvelenato beneficia di tutti i talenti e gli effetti che si attivano con Assalto Funesto o lo modificano.", nil, 0xdae3547b, nil, "um" },
  [425103] = { "Incidi sui tuoi stivali la runa Maestro di Scaltrezza:\n\n$I1\nGli attacchi sferrati in modalità furtiva e nei $N1 s successivi alla sua interruzione infliggono il $N2% di danni aggiuntivi.", nil, 0xb4456c3f, nil, "um" },
  [425170] = { "Incidi sui tuoi gambali la runa Vene Gelide:\n\n$I1\nAccelera il lancio d'incantesimi, aumentando la velocità di lancio del $N1% e riducendo del $N2% il ritardo subito dagli attacchi dannosi durante il lancio. Dura $D1.", nil, 0xe3b2f6e8, nil, "um" },
  [425171] = { "Incidi sui tuoi gambali la runa Eruzione Arcana:\n\n$I1\nScatena tutto il mana che ti rimane in un'ondata di energia concentrata sul bersaglio, infliggendo $N1 danni da arcano, aumentati fino al $N2% in base al mana rimanente. In seguito, la tua normale rigenerazione del mana si attiva e aumenta del $N3% per $D1.", nil, 0x5e00b891, nil, "um" },
  [425189] = { { "Incidi sui tuoi stivali la runa Chronostatic Preservation:\n\n$I1\nCura un bersaglio amico di $N1.", "Incidi sui tuoi stivali la runa Chronostatic Preservation:\n\n$I1\nFonde le magie arcana, del fuoco e del gelo per cristallizzare l'energia cronomantica in uno stato conservato da usare in seguito. Puoi trattenere questa energia per un massimo di $D1 prima che si consumi e svanisca. Quando viene scatenata, cura un bersaglio amico di $N2.\n\nQuesto incantesimo è considerato arcano, del fuoco e del gelo nelle interazioni con altri incantesimi, talenti ed effetti.", shape = { "1/0", "2/1" } }, nil, 0x1d4e262e, nil, "um" },
  [425213] = { "Incidi sui tuoi bracciali la runa Parola del Potere: Barriera:\n\n$I1\nEvoca una barriera sacra che protegge per $D1 tutti i membri del gruppo nel punto bersaglio, riducendo del $N2% tutti i danni subiti e impedendo che i danni ritardino il lancio d'incantesimi.", nil, 0x192ed3ca, nil, "um" },
  [425215] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Fede Distorta:\n\n$I1\nFlagello Mentale e Detonazione Mentale infliggono il $N1% di danni in più ai bersagli afflitti dal tuo Parola d'Ombra: Dolore.", nil, 0x66bd1c0b, nil, "um" },
  [425216] = { "Incidi sui tuoi stivali la runa Void Plague:\n\n$I1\nAffligge il bersaglio con una malattia che infligge $N1 danni da ombra in $D1.", nil, 0x42ee551e, nil, "um" },
  [425233] = { "Infligge danni da ombra a un nemico, ma genera un'elevata quantità di minaccia.", nil, 0xd6075571, nil, "um" },
  [425268] = { "Cura il bersaglio di $N1 in $D1.", "$N1 salute rigenerata ogni $N2 s.", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425269] = { "Cura il bersaglio di $N1 in $D1.", "$N1 salute rigenerata ogni $N2 s.", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425270] = { "Cura il bersaglio di $N1 in $D1.", "$N1 salute rigenerata ogni $N2 s.", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425271] = { "Cura il bersaglio di $N1 in $D1.", "$N1 salute rigenerata ogni $N2 s.", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425272] = { "Cura il bersaglio di $N1 in $D1.", "$N1 salute rigenerata ogni $N2 s.", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425273] = { "Cura il bersaglio di $N1 in $D1.", "$N1 salute rigenerata ogni $N2 s.", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425274] = { "Cura il bersaglio di $N1 in $D1.", "$N1 salute rigenerata ogni $N2 s.", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425275] = { "Cura il bersaglio di $N1 in $D1.", "$N1 salute rigenerata ogni $N2 s.", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425276] = { "Cura il bersaglio di $N1 in $D1.", "$N1 salute rigenerata ogni $N2 s.", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425277] = { "Cura il bersaglio di $N1 in $D1.", "$N1 salute rigenerata ogni $N2 s.", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425309] = { "Incidi sulla tua cintura la runa Rinnovamento Potenziato:\n\n$I1\nIl tuo Rinnovamento ora cura una volta in più subito, quando viene applicato, e ogni volta che cura beneficia del $N1% in più dei tuoi effetti di bonus alle cure.\n\nInoltre, il tuo Rinnovamento ora può essere attivo su bersagli che hanno già il Rinnovamento di un altro Sacerdote.", nil, 0xe14c3cd2, nil, "um" },
  [425310] = { "Incidi sulla tua cintura la runa Speranza Rinnovata:\n\n$I1\nLe tue cure di Cura Rapida, Cura Combinata, Cura Inferiore, Cura, Cura Maggiore e Contrizione ottengono il $N1% di probabilità di critico in più quando sono lanciate su bersagli con Anima Indebolita e riducono di $D1 la durata residua di Anima Indebolita sul bersaglio.", nil, 0x88a25871, nil, "um" },
  [425312] = { "Incidi sui tuoi stivali la runa Spirito del Redentore:\n\n$I1\nAttivala per diventare lo Spirito di Redenzione per $D1. In questa forma puoi lanciare qualsiasi incantesimo di cura senza costo, ma non puoi muoverti, attaccare, essere attaccato né essere bersaglio di incantesimi o effetti. Richiede il talento Spirito di Redenzione per l'attivazione, e non diventerai più Spirito di Redenzione quando muori.", nil, 0x10efc022, nil, "um" },
  [425314] = { "Incidi sui tuoi stivali la runa Dispersione:\n\n$I1\nTi disperdi in pura energia d'ombra, riducendo del $N1% tutti i danni subiti. Non puoi attaccare né lanciare incantesimi, ma rigeneri il $N2% del mana ogni $D1 per $D2. Dispersione può essere lanciata anche da stordito, impaurito o silenziato, al lancio rimuove tutti gli effetti di rallentamento e di limitazione al movimento e ti rende immune a essi mentre sei disperso.", nil, 0x0287aa9b, nil, "um" },
  [425336] = { "Aumenta la velocità d'attacco del $N1% per $D1.", "Velocità d'attacco aumentata del $N1%.", 0x7e4b2c7f, 0x8859e2db, "uu" },
  [425343] = { "Incidi sui tuoi gambali la runa Greater Ghost Wolf:\n\n$I1\nLa tua abilità ⟦Ghost Wolf=Lupo Spettrale⟧ ora può essere usata al chiuso e, mentre è attiva, riduce del $N1% tutti i danni che subisci.", nil, 0x0f11028d, nil, "um" },
  [425344] = { "Incidi sui tuoi guanti la runa ⟦Molten Blast=Detonazione Fusa⟧:\n\n$I1\nInveste fino a $N1 nemici in un cono davanti a te, infliggendo $N2 danni da fuoco. Questa abilità genera un'elevata quantità di minaccia. I danni periodici di Folgore del Fuoco hanno il $N3% di probabilità di azzerare il tempo di recupero di ⟦Molten Blast=Detonazione Fusa⟧.", nil, 0x23c7149c, nil, "um" },
  [425443] = { "Incidi sui tuoi guanti la runa Assalto Lampo:\n\n$I1\nUn attacco in mischia istantaneo e sconsiderato con l'arma a due mani che infligge $N1 danni fisici. Questa abilità beneficia di tutti gli effetti associati ad Assalto Eroico e li attiva.", nil, 0xfe2ebe8b, nil, "um" },
  [425444] = { "Incidi sulla tua armatura per il torso la runa Colpo Furente:\n\n$I1\nUn colpo feroce che infligge il $N1% dei danni dell'arma, ma che si può usare solo mentre Rabbia, Furia del Berserker o Rabbia del Sangue è attiva. Ogni altra abilità in mischia usata mentre Rabbia, Furia del Berserker o Rabbia del Sangue è attiva riduce di $D1 il tempo di recupero residuo di Colpo Furente.", nil, 0x95af0904, nil, "um" },
  [425445] = { "Incidi sulla tua armatura per il torso la runa Araldo della Guerra:\n\n$I1\nLe tue abilità Carica, Intercettazione e Intervento ora sono utilizzabili in combattimento e in qualsiasi postura, e quando vengono attivate rimuovono tutti gli effetti di limitazione al movimento.", nil, 0xd9810bbd, nil, "um" },
  [425446] = { "Incidi sui tuoi gambali la runa Consumed by Rage:\n\n$I1\nTi rende infuriato (attivando le abilità che richiedono di essere infuriato) per $D1 dopo che hai superato $N2 rabbia. Inoltre, mentre sei infuriato, Turbine colpisce anche con le armi da mischia nella mano secondaria.", nil, 0x002a5c3b, nil, "um" },
  [425447] = { "Incidi sui tuoi gambali la runa Assalto Furioso:\n\n$I1\nMentre impugni armi a $N1 mani, la tua velocità d'attacco aumenta del $N2% e i tuoi colpi in mischia andati a segno generano $N3 rabbia aggiuntiva, o $N4 rabbia aggiuntiva se sono critici.", nil, 0x17dbef85, nil, "um" },
  [425476] = { "Incidi sui tuoi gambali la runa Demonic Pact:\n\n$I1\nL'effetto del tuo Sacrificio Demoniaco non viene più annullato quando evochi un altro famiglio demoniaco. Evocare di nuovo il famiglio sacrificato annulla comunque l'effetto.", nil, 0x15896149, nil, "um" },
  [425477] = { "Incidi sui tuoi gambali la runa Demonic Grace:\n\n$I1\nTi pervade di vil energia, aumentando del $N1% la probabilità di schivata tua e del tuo famiglio e del $N2% la tua probabilità di critico con tutti gli attacchi. Dura $D1.", nil, 0x08b6b628, nil, "um" },
  [425618] = { "Incidi sulla tua armatura per il torso la runa Suolo Santificato:\n\n$I1\nLa tua Consacrazione ora cura anche i membri del gruppo nella sua area del $N1% del valore dei danni di Consacrazione.", nil, 0x96d0ec24, nil, "um" },
  [425619] = { "Incidi sulla tua armatura per il torso la runa Aegis:\n\n$I1\nAumenta del $N1% il tuo indice di blocco e modifica il tuo talento Trincea. Trincea ora ha anche il $N2% di probabilità di attivarsi con qualsiasi attacco in mischia o a distanza contro di te e si attiva sempre quando infliggi un critico in mischia. Inoltre, il tuo talento Regolamento di Conti ottiene il $N3% di probabilità per punto talento di attivarsi con qualsiasi attacco in mischia o a distanza contro di te.", nil, 0x4ecc3126, nil, "um" },
  [425621] = { "Incidi sui tuoi gambali la runa Predica:\n\n$I1\nInterrompe il lancio d'incantesimi e impedisce di lanciare incantesimi di quella scuola per $D1.", nil, 0x69981c41, nil, "um" },
  [425728] = { "Morde il bersaglio, infliggendo $N1 danni da natura in $D1. Su ogni bersaglio può essere attivo un solo Morso per Cacciatore.", nil, 0x7d1286a5, nil, "um" },
  [425729] = { "Morde il bersaglio, infliggendo $N1 danni da natura in $D1. Su ogni bersaglio può essere attivo un solo Morso per Cacciatore.", nil, 0x7d1286a5, nil, "um" },
