  [425734] = { "Morde il bersaglio, infliggendo $N1 danni da natura in $D1. Su ogni bersaglio può essere attivo un solo Morso per Cacciatore.", nil, 0x7d1286a5, nil, "um" },
  [425735] = { "Morde il bersaglio, infliggendo $N1 danni da natura in $D1. Su ogni bersaglio può essere attivo un solo Morso per Cacciatore.", nil, 0x7d1286a5, nil, "um" },
  [425736] = { "Morde il bersaglio, infliggendo $N1 danni da natura in $D1. Su ogni bersaglio può essere attivo un solo Morso per Cacciatore.", nil, 0x7d1286a5, nil, "um" },
  [425737] = { "Morde il bersaglio, infliggendo $N1 danni da natura in $D1. Su ogni bersaglio può essere attivo un solo Morso per Cacciatore.", nil, 0x7d1286a5, nil, "um" },
  [425758] = { "Incidi sui tuoi guanti la runa Scorticatura:\n\n$I1\nUn attacco ad ampio raggio che colpisce con le armi da mischia tutti i nemici davanti a te, infliggendo il $N1% dei danni dell'arma. Il tuo bersaglio principale subisce il $N2% di danni in più.", nil, 0x3c61f546, nil, "um" },
  [425759] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Cobra Strikes:\n\n$I1\nI tuoi colpi critici con le abilità di tiro e di assalto e con Morso della Mangusta rendono critici i prossimi $N1 attacchi speciali del tuo famiglio.", nil, 0xd5359e71, nil, "um" },
  [425760] = { "Incidi sui tuoi gambali la runa Serpent Spread:\n\n$I1\nI bersagli colpiti dal tuo Tiro Multiplo vengono afflitti anche dal tuo Morso del Serpente per $D1.", nil, 0x5f415872, nil, "um" },
  [425762] = { "Incidi sui tuoi gambali la runa Assalto Fiancheggiato:\n\n$I1\nTu e il tuo famiglio infliggete simultaneamente e istantaneamente il $N1% dei danni in mischia. In seguito, infliggi il $N2% di danni in più per $D1, effetto cumulabile fino a $N4 volte. Gli attacchi base del tuo famiglio hanno il $N5% di probabilità di azzerare il tempo di recupero di Assalto Fiancheggiato.", nil, 0x2cd65e38, nil, "um" },
  [425882] = { "Incidi sui tuoi stivali la runa Decoy Totem:\n\n$I1\nEvoca ai piedi del bersaglio un Decoy Totem con $N2 salute per $D1, che devia sul totem il prossimo attacco in mischia o a distanza sferrato contro il bersaglio. Il totem rende inoltre il bersaglio immune agli effetti di limitazione al movimento per $D2.", nil, 0x8e83f725, nil, "um" },
  [425883] = { "Incidi sui tuoi stivali la runa Risveglio Ancestrale:\n\n$I1\nQuando curi in modo critico con Ondata di Cura o Ondata di Cura Inferiore, evochi uno spirito ancestrale che ti aiuta curando istantaneamente il membro del gruppo con la percentuale di salute più bassa entro $N1 m del $N2% della quantità curata.", nil, 0x93669494, nil, "um" },
  [425895] = { "Infligge $N1 danni da gelo a un nemico.", nil, 0xe9a78e07, nil, "um" },
})
